Rule.Source:
String empNo = account.getStringAttribute("employeeNumber");
String first = account.getStringAttribute("firstName");
String last  = account.getStringAttribute("lastName");

if (empNo != null) {
    identity.setName(empNo);
    identity.setAttribute("employeeNumber", empNo);
}
if (first != null) identity.setFirstname(first);
if (last  != null) identity.setLastname(last);

StringBuilder dn = new StringBuilder();
if (first != null) dn.append(first);
if (last  != null) dn.append(dn.length() > 0 ? " " : "").append(last);
if (dn.length() > 0) identity.setDisplayName(dn.toString());

// Contractors / Interns are flagged as non-employees
String type = account.getStringAttribute("employeeType");
identity.setType("Employee".equalsIgnoreCase(type) ? "employee" : "contractor");
